package dev.gbppimentel.zzz;
import java.nio.file.*;import java.io.*;import java.awt.image.*;import javax.imageio.*;import org.json.*;import java.util.*;
public final class PortraitCatalogTest {
 public static void main(String[] args)throws Exception{JSONArray bank=new JSONArray(Files.readString(Path.of("assets/portraits.json")));Set<String> ids=new HashSet<>();try(var paths=Files.list(Path.of("reference/hud-public"))){for(Path path:(Iterable<Path>)paths.filter(p->p.toString().endsWith(".png")&&p.getFileName().toString().matches("[0-9]+\\.png"))::iterator){BufferedImage im=ImageIO.read(path.toFile());String id=path.getFileName().toString().replace(".png","");PortraitFeatures.append(bank,id,im.getRGB(0,0,im.getWidth(),im.getHeight(),null,0,im.getWidth()),im.getWidth(),im.getHeight());ids.add(id);}}
 JSONArray roster=new JSONObject(Files.readString(Path.of("private/device-state.json"))).getJSONObject("sections").getJSONObject("roster").getJSONObject("data").getJSONArray("avatar_list");for(int i=0;i<roster.length();i++)if(!ids.contains(roster.getJSONObject(i).get("id").toString()))throw new AssertionError("Missing linked-roster public portrait");PortraitMatcher matcher=new PortraitMatcher(bank.toString());
 for(String[] c:new String[][]{{"bugs-combat.png","1211"},{"bugs-combat2.png","1211"},{"bugs-combat3.png","1101"},{"bugs-combat4.png","1611"}}){BufferedImage im=ImageIO.read(new File("private/calibration/"+c[0]));JSONArray found=matcher.find(im.getRGB(0,0,im.getWidth(),im.getHeight(),null,0,im.getWidth()),im.getWidth(),im.getHeight(),"combat");System.out.println("Production public model "+c[0]+": "+found);if(found.length()!=3||!found.getJSONObject(0).getString("id").equals(c[1]))throw new AssertionError("Runtime catalog registration differs from build model");}
 System.out.println("All "+ids.size()+" linked-roster portraits covered; runtime model passed four held-out HUD frames");}
}
